css:
.loader { position: relative; display: inline-flex; align-items: center; justify-content: center; width: var(--loader-size); height: var(--loader-size); }
.loader .ring { position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: 9999px; border: calc(var(--loader-size) * .07) solid color-mix(in srgb, var(--loader-color) 20%, transparent); border-top-color: var(--loader-color); border-right-color: var(--loader-color); animation: twSpin calc(var(--loader-speed) * 1.1) linear infinite; }
.loader .play { position: relative; width: 0; height: 0; margin-left: 8%; border-top: calc(var(--loader-size) * .15) solid transparent; border-bottom: calc(var(--loader-size) * .15) solid transparent; border-left: calc(var(--loader-size) * .25) solid var(--loader-color); animation: twBeat calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
@keyframes twSpin { to { transform: rotate(360deg); } }
@keyframes twBeat { 0%, 100% { opacity: .5; transform: scale(.88); } 50% { opacity: 1; transform: scale(1); } }
